/**
 * T-1187 · Close the highest-risk test gaps in clients/app/src/state/appearance.js:1-29.
 *
 * Source under test: clients/app/src/state/appearance.js, lines 1-29 inclusive (the whole
 * boot, generated by tools/gen_ui.py:132 render_appearance_js). It is evaluated here with
 * node:vm against synthetic `document`, `localStorage` and `<meta>` seams only: no browser,
 * no React, no TypeScript loader, no new dependency, no network, no subprocess. The expected
 * theme colours are read from clients/app/tokens/tokens.json, which is the same source
 * tools/gen_ui.py:134 uses to emit the `BG` literal at appearance.js:8, so the colour
 * expectations are independent of the string under test.
 *
 * Coverage read first (all of it stays read-only context for this file):
 *   - tests/v1/e2e/test_spa_appearance.py:43,49,68,73,91  (real browser; never feeds a
 *     hostile or broken storage value, and never asserts the dark-choice meta colours)
 *   - clients/app/test/shell.test.ts:66-71 (the neighbouring node:test style; its sources()
 *     filter is /\.tsx?$/, so this .js file is never even read by the node suite)
 *   - clients/app/index.html:6-9 (always ships 2 theme-color metas + a color-scheme meta,
 *     so the absent-node branches never occur in the e2e)
 *   - clients/app/src/surfaces/Control.tsx:815-833 (the caller contract on the return value)
 *
 * The ten final selected branches, ranked by risk (see /work/QWEN-DONE-T-1187.md for the
 * evidence trail from the card's ten starting probes, and for the one defect kept as an
 * expected failure):
 *   1  G01  appearance.js:16,17  a theme/contrast name that only exists on a prototype is
 *                                denied (hasOwnProperty / indexOf, not `in`, not truthiness)
 *   2  G02  appearance.js:9-15,29  storage unreachable (identifier or getItem throws): the
 *                                boot at :29 still completes and fails closed to system/system
 *   3  G06  appearance.js:17  contrast is validated independently of theme, both arms
 *   4  G05  appearance.js:16,17  null / scalar / array payloads take the `p &&` short-circuit
 *                                instead of throwing out of the boot
 *   5  G03  appearance.js:10,14  a throwing setter keeps this page on the chosen look and
 *                                never resurrects the stale stored bytes (:14 `next || null`)
 *   6  G10  appearance.js:10-11,21,26,27  the page shows what storage read back, not the
 *                                argument; repeated calls leave no stale choice; the exact
 *                                ordered effect trace; the return shape Control.tsx:825 needs
 *   7  G07  appearance.js:23,26  an explicit theme overrides every OS-tuned theme-color meta
 *                                (the false arm of both ternaries, incl. the light-media meta)
 *   8  G04  appearance.js:11-14  malformed JSON falls back to system/system and storage is
 *                                never "repaired" by a write
 *   9  G08  appearance.js:21-22  `system` maps each meta's own media, incl. the falsy arm of
 *                                `m.getAttribute('media') || ''` at :22
 *   10 G09  appearance.js:21,26  no theme-color meta and no color-scheme meta: nothing throws,
 *                                nothing is invented; a broken document or a refusing meta or a
 *                                lost querySelectorAll all fail loud, and are never swallowed
 *   EF1  appearance.js:10 vs 16-17  a choice the parser denies is nevertheless persisted.
 *        Kept as a strict expected-failure wrapper (it fails on an unexpected pass).
 *
 * Independent by construction: nothing is imported from any other test_gaps3 file and no
 * test depends on queue order. Every OS-specific behaviour (media queries, storage faults,
 * the Windows contrast themes the Control hint mentions) is faked through these seams, so
 * this file behaves the same on Linux and Windows.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const SOURCE_PATH = fileURLToPath(new URL('../src/state/appearance.js', import.meta.url));
const SOURCE = readFileSync(SOURCE_PATH, 'utf8');
const TOKENS_PATH = fileURLToPath(new URL('../tokens/tokens.json', import.meta.url));
const THEME_BG = (() => {
  const themes = JSON.parse(readFileSync(TOKENS_PATH, 'utf8')).themes;
  return { dark: themes.dark.bg, light: themes.light.bg };
})();

/** The storage key of appearance.js:8 (also tools/gen_ui.py:45 APPEARANCE_KEY). */
const KEY = 'archeus-appearance';
const MISSING = Symbol('nothing stored');
/** What index.html:7-8 actually ships, in that order. */
const OS_METAS = ['(prefers-color-scheme: dark)', '(prefers-color-scheme: light)'];

/** One synthetic element: it records every attribute read and write, raw, and can be armed. */
function makeNode(effects, kind, attrs = {}, faults = {}) {
  const node = {
    kind,
    attrs: { ...attrs },
    writes: [],
    reads: [],
    faults,
    getAttribute(name) {
      node.reads.push(name);
      effects.push(['getAttribute', kind, name]);
      if (node.faults.getAttribute) throw node.faults.getAttribute;
      return Object.prototype.hasOwnProperty.call(node.attrs, name) ? node.attrs[name] : null;
    },
    setAttribute(name, value) {
      node.writes.push([name, value]);
      effects.push(['setAttribute', kind, name, value]);
      if (node.faults.setAttribute) throw node.faults.setAttribute;
      node.attrs[name] = value;
    },
    /** the last value handed to setAttribute for `name`, raw (a leak is not a string) */
    last(name) {
      for (let i = node.writes.length - 1; i >= 0; i -= 1) {
        if (node.writes[i][0] === name) return node.writes[i][1];
      }
      return undefined;
    },
  };
  return node;
}

/** In-memory storage: invented values only, never the host's, and it can be armed to throw. */
function makeStorage(effects, { value = MISSING, blackHole = false, faults = {} } = {}) {
  const raw = Object.create(null);
  if (value !== MISSING) raw[KEY] = value;
  const api = {
    getItem(name) {
      effects.push(['getItem', name]);
      if (faults.getItem) throw faults.getItem;
      return Object.prototype.hasOwnProperty.call(raw, name) ? raw[name] : null;
    },
    setItem(name, value2) {
      effects.push(['setItem', name, value2]);
      if (faults.setItem) throw faults.setItem;
      if (!blackHole) raw[name] = String(value2);
    },
    // the boot has no business tidying up after itself: these are recorded, never allowed
    removeItem(name) { effects.push(['removeItem', name]); },
    clear() { effects.push(['clear']); },
    key(i) { effects.push(['key', i]); return null; },
    get length() { effects.push(['length']); return 0; },
  };
  return { api, raw, faults };
}

/** Globals the boot must never touch. Reading or calling one records it and throws. */
function privileged(effects) {
  const tripCall = (name) => function () {
    effects.push(['privileged:' + name]);
    throw new Error('T-1187 seam: the appearance boot must not call ' + name);
  };
  const tripObject = (name) => new Proxy(Object.create(null), {
    get(_t, k) {
      effects.push(['privileged:' + name + '.' + String(k)]);
      throw new Error('T-1187 seam: the appearance boot must not read ' + name + '.' + String(k));
    },
    has(_t, k) { effects.push(['privileged:' + name + ' in ' + String(k)]); return false; },
  });
  return {
    fetch: tripCall('fetch'), alert: tripCall('alert'), require: tripCall('require'),
    setTimeout: tripCall('setTimeout'), setInterval: tripCall('setInterval'),
    requestAnimationFrame: tripCall('requestAnimationFrame'),
    importScripts: tripCall('importScripts'), eval: tripCall('eval'),
    XMLHttpRequest: tripCall('XMLHttpRequest'), WebSocket: tripCall('WebSocket'),
    Worker: tripCall('Worker'),
    navigator: tripObject('navigator'), location: tripObject('location'),
    indexedDB: tripObject('indexedDB'), caches: tripObject('caches'),
    history: tripObject('history'), screen: tripObject('screen'), process: tripObject('process'),
  };
}

/**
 * Build a page, run the source through it (which runs the boot at appearance.js:29) and
 * hand back every seam so a test can look at what the boot actually did.
 */
function world(spec = {}) {
  const effects = [];
  const storage = makeStorage(effects, spec.storage);
  const html = spec.htmlNull ? null : makeNode(effects, 'html', spec.htmlAttrs || {}, spec.htmlFaults || {});
  const metas = (spec.metas || OS_METAS).map((m, i) => {
    const attrs = { name: 'theme-color' };
    if (m !== undefined && m !== null) attrs.media = m;
    return makeNode(effects, 'theme-color', attrs, (spec.metaFaults && spec.metaFaults[i]) || {});
  });
  const scheme = spec.scheme === null ? null
    : makeNode(effects, 'color-scheme', { name: 'color-scheme', content: 'dark light' }, spec.schemeFaults || {});
  const doc = {
    documentElement: html,
    querySelectorAll(selector) {
      effects.push(['querySelectorAll', selector]);
      if (spec.faults && spec.faults.querySelectorAll) throw spec.faults.querySelectorAll;
      return selector === 'meta[name="theme-color"]' ? metas.slice() : [];
    },
    querySelector(selector) {
      effects.push(['querySelector', selector]);
      if (spec.faults && spec.faults.querySelector) throw spec.faults.querySelector;
      return selector === 'meta[name="color-scheme"]' ? scheme : null;
    },
    createElement(tag) {
      effects.push(['createElement', tag]);
      throw new Error('T-1187 seam: the appearance boot must not invent a <' + tag + '>');
    },
    get cookie() { effects.push(['privileged:document.cookie']); throw new Error('T-1187 seam: no cookies'); },
    get location() { effects.push(['privileged:document.location']); throw new Error('T-1187 seam: no navigation'); },
  };
  const sandbox = Object.assign({ document: doc }, privileged(effects));
  if (spec.localStorageFault) {
    // the real disabled-storage case: reading the `localStorage` identifier itself throws
    Object.defineProperty(sandbox, 'localStorage', {
      configurable: true, enumerable: true, get() { effects.push(['localStorage']); throw spec.localStorageFault; },
    });
  } else {
    sandbox.localStorage = storage.api;
  }
  const context = vm.createContext(sandbox);
  let bootError = null;
  try {
    vm.runInContext(SOURCE, context, { filename: 'appearance.js' });
  } catch (e) {
    bootError = e;
  }
  return {
    sandbox, storage, html, metas, scheme, doc, effects, bootError,
    /** the ordered effect trace, optionally since the last mark() */
    seams(since) { return since === undefined ? effects.slice() : effects.slice(since); },
    mark() { return effects.length; },
    names(since) { return (since === undefined ? effects : effects.slice(since)).map((e) => e[0]); },
    /** the returned choice, copied into this realm: a vm object is never prototype-equal to a literal */
    call(next) { return Object.assign({}, sandbox.archeusAppearance(next)); },
    contents() { return metas.map((m) => m.last('content')); },
  };
}

function assertNoPrivilegedAccess(w) {
  const hits = w.seams().filter((e) => String(e[0]).startsWith('privileged:'));
  assert.deepEqual(hits, [], 'the boot touched a privileged seam: ' + JSON.stringify(hits));
}

/* ------------------------------------------------------------------ 1: denial of what is ours */

const PROTO_THEME_KEYS = ['constructor', 'toString', 'hasOwnProperty', 'valueOf', 'isPrototypeOf', '__proto__'];

test('T-1187 G01 appearance.js:16,17 a theme or contrast name that only lives on a prototype is denied', () => {
  for (const key of PROTO_THEME_KEYS) {
    const w = world({ storage: { value: JSON.stringify({ theme: key, contrast: 'high' }) } });
    assert.equal(w.bootError, null, key + ': ' + w.bootError);
    assert.equal(w.html.attrs['data-theme'], 'system', 'theme ' + key + ' is no theme');
    assert.equal(w.html.attrs['data-contrast'], 'high', 'denying the theme must not drag the contrast in');
    assert.deepEqual(w.call(), { theme: 'system', contrast: 'high' }, 'and the boot says so too');
    // `in`/truthiness instead of hasOwnProperty would hand back a host object or a function here
    for (const c of w.contents()) {
      assert.equal(typeof c, 'string', 'a meta content is never a ' + (c && c.constructor && c.constructor.name));
      assert.ok(c === THEME_BG.dark || c === THEME_BG.light, 'a meta is a token bg or nothing: ' + c);
    }
    assert.equal(w.scheme.last('content'), 'dark light');
    assertNoPrivilegedAccess(w);
  }
  for (const key of ['constructor', 'length', 'indexOf', 'toString', 'concat', '__proto__']) {
    const w = world({ storage: { value: JSON.stringify({ theme: 'dark', contrast: key }) } });
    assert.equal(w.bootError, null, key + ': ' + w.bootError);
    assert.equal(w.html.attrs['data-theme'], 'dark', 'the valid theme stays (contrast ' + key + ')');
    assert.equal(w.html.attrs['data-contrast'], 'system', 'contrast ' + key + ' is no contrast');
    assert.deepEqual(w.call(), { theme: 'dark', contrast: 'system' }, 'and the boot says so too');
    for (const c of w.contents()) {
      assert.equal(typeof c, 'string', 'a contrast leak would put a ' + typeof c + ' in the meta');
      assert.equal(c, THEME_BG.dark, 'contrast never tints the theme-colour metas');
    }
    assert.equal(w.scheme.last('content'), 'dark');
    assertNoPrivilegedAccess(w);
  }
});

test('T-1187 G06 appearance.js:17 contrast is validated on its own, both arms, never beside theme', () => {
  const CASES = [
    [{ theme: 'dark', contrast: 'ULTRA' }, 'dark', 'system'],
    [{ theme: 'light', contrast: 'Standard' }, 'light', 'system'], // plain JS string compare, not the OS
    [{ theme: 'dark', contrast: 'high ' }, 'dark', 'system'],
    [{ theme: 'tokyo-night', contrast: 'high' }, 'system', 'high'],
    [{ theme: 'dark' }, 'dark', 'system'],
    [{ contrast: 'standard' }, 'system', 'standard'],
    [{ theme: 'dark', contrast: null }, 'dark', 'system'],
    [{ theme: 'dark', contrast: 1 }, 'dark', 'system'],
    [{ theme: 'dark', contrast: ['high'] }, 'dark', 'system'], // indexOf compares strictly
    [{ theme: 'dark', contrast: 'high' }, 'dark', 'high'],
    [{ theme: 'light', contrast: 'standard' }, 'light', 'standard'],
  ];
  for (const [stored, theme, contrast] of CASES) {
    const w = world({ storage: { value: JSON.stringify(stored) } });
    assert.equal(w.bootError, null, JSON.stringify(stored) + ': ' + w.bootError);
    assert.deepEqual(w.call(), { theme, contrast }, JSON.stringify(stored));
    assert.deepEqual(w.html.attrs, { 'data-theme': theme, 'data-contrast': contrast }, JSON.stringify(stored));
    const bg = theme === 'system' ? null : THEME_BG[theme];
    for (const c of w.contents()) {
      assert.equal(typeof c, 'string');
      if (bg !== null) assert.equal(c, bg, 'contrast ' + contrast + ' must not tint the metas');
    }
    assert.equal(w.scheme.last('content'), theme === 'system' ? 'dark light' : theme);
    assertNoPrivilegedAccess(w);
  }
});

test('T-1187 G05 appearance.js:16,17 null, scalar and array payloads take the `p &&` short-circuit', () => {
  for (const shape of ['null', '0', 'false', '""', '123', '"dark"', '"system"', '[]', '[1,2]', '{}',
    '{"theme":null}', '{"theme":{}}', '{"theme":[],"contrast":[]}']) {
    const w = world({ storage: { value: shape } });
    assert.equal(w.bootError, null, shape + ': the boot must not die on ' + shape);
    const at = w.mark();
    assert.deepEqual(w.call(), { theme: 'system', contrast: 'system' }, shape);
    assert.deepEqual(w.html.attrs, { 'data-theme': 'system', 'data-contrast': 'system' }, shape);
    assert.deepEqual(w.names(at), ['getItem', 'setAttribute', 'setAttribute', 'querySelectorAll',
      'getAttribute', 'setAttribute', 'getAttribute', 'setAttribute', 'querySelector', 'setAttribute'],
    'no second read, no repair write for ' + shape);
    assert.equal(w.storage.raw[KEY], shape, shape + ' is left where it is');
    assertNoPrivilegedAccess(w);
  }
  // boundary: a property lookup coerces, indexOf does not, so an array theme arrives as `dark`
  const w = world({ storage: { value: '{"theme":["dark"],"contrast":["high"]}' } });
  assert.equal(String(w.html.attrs['data-theme']), 'dark', 'the page-visible theme of ["dark"]');
  assert.equal(String(w.html.attrs['data-contrast']), 'system', '["high"] is not in CONTRASTS');
  for (const c of w.contents()) assert.equal(c, THEME_BG.dark);
});

/* --------------------------------------------------------------------------- 2: fault paths */

test('T-1187 G02 appearance.js:9-15,29 storage that is not reachable at all still boots, fail-closed', () => {
  // (a) the real "user blocked storage" case: even the identifier throws
  const blocked = world({ localStorageFault: new Error('SecurityError: storage is blocked') });
  assert.equal(blocked.bootError, null, 'a storage fault must never escape the boot at appearance.js:29');
  assert.deepEqual(blocked.html.attrs, { 'data-theme': 'system', 'data-contrast': 'system' });
  assert.deepEqual(blocked.contents(), [THEME_BG.dark, THEME_BG.light], 'still follows the OS metas');
  assert.equal(blocked.scheme.last('content'), 'dark light');
  // the page choice still holds without storage (appearance.js:14), and nothing is written
  assert.deepEqual(blocked.call({ theme: 'dark', contrast: 'high' }), { theme: 'dark', contrast: 'high' });
  assert.deepEqual(blocked.html.attrs, { 'data-theme': 'dark', 'data-contrast': 'high' });
  assert.deepEqual(blocked.seams(blocked.mark()).filter((e) => e[0] === 'setItem'), [], 'a blocked store is not retried');
  assertNoPrivilegedAccess(blocked);

  // (b) getItem throws while setItem works
  const w = world({ storage: { value: '{"theme":"dark","contrast":"high"}', faults: { getItem: new Error('SecurityError') } } });
  assert.equal(w.bootError, null);
  assert.deepEqual(w.html.attrs, { 'data-theme': 'system', 'data-contrast': 'system' }, 'fail closed, not stale');
  assert.deepEqual(w.names(), ['getItem', 'setAttribute', 'setAttribute', 'querySelectorAll',
    'getAttribute', 'setAttribute', 'getAttribute', 'setAttribute', 'querySelector', 'setAttribute'],
  'one read attempt, no retry, no write-back');
  assert.deepEqual(w.contents(), [THEME_BG.dark, THEME_BG.light], 'one read attempt failed, so system follows the OS metas');
  assert.equal(w.scheme.last('content'), 'dark light');
  assert.equal(w.storage.raw[KEY], '{"theme":"dark","contrast":"high"}', 'a broken read never rewrites storage');
  assertNoPrivilegedAccess(w);
});

test('T-1187 G03 appearance.js:10,14 a throwing setter keeps this page on the chosen look, not on the stale bytes', () => {
  const stale = JSON.stringify({ theme: 'dark', contrast: 'standard' });
  const w = world({ storage: { value: stale, faults: { setItem: new Error('QuotaExceededError') } } });
  assert.equal(w.bootError, null);
  assert.deepEqual(w.html.attrs, { 'data-theme': 'dark', 'data-contrast': 'standard' }, 'the boot read the stale choice');
  const at = w.mark();
  assert.deepEqual(w.call({ theme: 'light', contrast: 'high' }), { theme: 'light', contrast: 'high' },
    'appearance.js:14 `next || null` is what holds the choice for this page');
  assert.deepEqual(w.html.attrs, { 'data-theme': 'light', 'data-contrast': 'high' });
  assert.deepEqual(w.contents(), [THEME_BG.light, THEME_BG.light], 'no dark meta is left behind');
  assert.equal(w.scheme.last('content'), 'light');
  assert.deepEqual(w.seams(at).filter((e) => ['setItem', 'getItem', 'removeItem', 'clear', 'key', 'length'].includes(e[0])),
    [['setItem', KEY, '{"theme":"light","contrast":"high"}']],
    'the failed write is the last storage touch: :11 is never reached, so the stale bytes are not re-read');
  assert.equal(w.storage.raw[KEY], stale, 'the stored bytes are exactly as found');
  assertNoPrivilegedAccess(w);
});

test('T-1187 G04 appearance.js:11-14 malformed JSON falls back to system and is never "repaired"', () => {
  for (const bad of ['{"theme":dark', '', '{', 'undefined', 'null,', '{"theme":"dark"', '  ', '"unterminated']) {
    const w = world({ storage: { value: bad } });
    assert.equal(w.bootError, null, JSON.stringify(bad) + ': a broken value must not kill the boot');
    assert.deepEqual(w.html.attrs, { 'data-theme': 'system', 'data-contrast': 'system' }, JSON.stringify(bad));
    assert.deepEqual(w.call(), { theme: 'system', contrast: 'system' }, JSON.stringify(bad));
    assert.equal(w.storage.raw[KEY], bad, JSON.stringify(bad) + ' is left alone: no write-back, no removeItem');
    assert.deepEqual(w.names().filter((n) => n === 'setItem' || n === 'removeItem' || n === 'clear'), [],
      JSON.stringify(bad) + ' must not be tidied up');
    for (const c of w.contents()) assert.ok(c === THEME_BG.dark || c === THEME_BG.light, String(c));
    assert.equal(w.scheme.last('content'), 'dark light');
    assertNoPrivilegedAccess(w);
  }
  // the same catch with a choice in hand: it holds for this page (appearance.js:14)
  const w = world({ storage: { value: 'not json at all' } });
  assert.deepEqual(w.call({ theme: 'light', contrast: 'standard' }), { theme: 'light', contrast: 'standard' });
  assert.deepEqual(w.html.attrs, { 'data-theme': 'light', 'data-contrast': 'standard' });
  assert.equal(w.storage.raw[KEY], '{"theme":"light","contrast":"standard"}',
    'a choice handed in is stored at :10 first, then the broken read at :11 is caught at :12');
});

/* ------------------------------------------------------------------------- 3: boundaries */

test('T-1187 G07 appearance.js:23,26 an explicit theme overrides the OS on every meta, both ternaries', () => {
  const w = world({ metas: ['(prefers-color-scheme: light)', '(prefers-color-scheme: dark)', undefined] });
  assert.deepEqual(w.contents(), [THEME_BG.light, THEME_BG.dark, THEME_BG.dark], 'the boot follows the OS');
  w.call({ theme: 'dark', contrast: 'standard' });
  assert.deepEqual(w.contents(), [THEME_BG.dark, THEME_BG.dark, THEME_BG.dark],
    'the false arm of :23 wins: even the light-media meta wears the chosen dark');
  assert.equal(w.scheme.last('content'), 'dark', 'and :26 does not keep saying "dark light"');
  w.call({ theme: 'light', contrast: 'high' });
  assert.deepEqual(w.contents(), [THEME_BG.light, THEME_BG.light, THEME_BG.light],
    'flipping the choice flips every meta, including the dark-media one');
  assert.equal(w.scheme.last('content'), 'light');
  assert.equal(w.html.attrs['data-theme'], 'light');
  assert.equal(w.html.attrs['data-contrast'], 'high');
  assertNoPrivilegedAccess(w);
});

test('T-1187 G08 appearance.js:21-22 system maps each meta onto its own media, defaulting to dark', () => {
  const w = world({ metas: ['(prefers-color-scheme: light)', '(prefers-color-scheme: dark)', undefined,
    '(PREFERS-COLOR-SCHEME: LIGHT)', '(prefers-color-scheme: light) and (min-width: 40rem)', ''] });
  assert.deepEqual(w.call({ theme: 'system', contrast: 'system' }), { theme: 'system', contrast: 'system' });
  assert.deepEqual(w.contents(), [THEME_BG.light, THEME_BG.dark, THEME_BG.dark, THEME_BG.dark,
    THEME_BG.light, THEME_BG.dark], 'each meta is looked up on its own media string');
  assert.equal(w.scheme.last('content'), 'dark light');
  assert.deepEqual(w.metas[2].reads, ['media', 'media'], 'a meta with no media attribute is read, then treated as dark');
  assert.equal(w.names().filter((n) => n === 'getAttribute').length, 12, 'each of the 6 metas is asked once per pass, twice here');
  // and the media answer is ignored once a choice is made
  w.call({ theme: 'dark', contrast: 'system' });
  assert.deepEqual(w.contents(), [THEME_BG.dark, THEME_BG.dark, THEME_BG.dark, THEME_BG.dark,
    THEME_BG.dark, THEME_BG.dark]);
  assertNoPrivilegedAccess(w);
});

test('T-1187 G09 appearance.js:21,26 a missing meta is never invented and never thrown over', () => {
  const w = world({ metas: [], scheme: null });
  assert.equal(w.bootError, null, 'no theme-color meta and no color-scheme meta must not throw at :21 or :26');
  const at0 = w.mark();
  assert.deepEqual(w.call({ theme: 'dark', contrast: 'high' }), { theme: 'dark', contrast: 'high' });
  assert.deepEqual(w.html.attrs, { 'data-theme': 'dark', 'data-contrast': 'high' }, 'the choice still lands');
  assert.deepEqual(w.names(at0), ['setItem', 'getItem', 'setAttribute', 'setAttribute', 'querySelectorAll',
    'querySelector'], 'nothing is created, nothing is written that was not asked for');
  assertNoPrivilegedAccess(w);

  // an empty list plus a present scheme: the scheme is still kept honest
  const w2 = world({ metas: [], scheme: 'present' });
  w2.call({ theme: 'light', contrast: 'standard' });
  assert.equal(w2.scheme.last('content'), 'light');
  assert.deepEqual(w2.contents(), []);

  // a meta that refuses to be written fails loud, after <html> is already on the new look
  const w3 = world({ metas: ['(prefers-color-scheme: light)', '(prefers-color-scheme: dark)'] });
  assert.equal(w3.bootError, null, 'a healthy page boots fine before the fault is armed');
  w3.metas[1].faults.setAttribute = new Error('T-1187 seam: meta refused the write');
  const at = w3.mark();
  assert.throws(() => w3.call({ theme: 'dark', contrast: 'high' }),
    /T-1187 seam: meta refused the write/,
    'appearance.js:21-24 is outside the try: a half-applied look is never swallowed');
  const trace = w3.seams(at).map((e) => e[0]);
  assert.deepEqual(trace.slice(0, 4), ['setItem', 'getItem', 'setAttribute', 'setAttribute'],
    '<html> is written before the metas, so the failure is visible and ordered');
  assert.equal(w3.html.attrs['data-theme'], 'dark');

  // an unusable <html> is never silently painted over: the writes at :19-20 are outside the try
  const w4 = world({ htmlNull: true });
  assert.ok(w4.bootError, 'a boot that cannot reach <html> must say so, not carry on');
  assert.equal(w4.bootError.constructor.name, 'TypeError', 'appearance.js:19-20 is not inside the try at :9');
  assert.deepEqual(w4.names().filter((n) => n === 'setAttribute'), [], 'nothing is written behind the back of a broken document');

  // and neither is the meta pass: a boot that cannot reach the metas does not claim to have styled
  const w5 = world({ faults: { querySelectorAll: new Error('T-1187 seam: the metas are unreachable') } });
  assert.ok(w5.bootError, 'the boot at appearance.js:29 propagates a meta fault, it is caught by nothing');
  assert.equal(w5.bootError.message, 'T-1187 seam: the metas are unreachable');
  assert.equal(w5.scheme.writes.length, 0, 'a half-styled page is not completed behind the fault');
});

test('T-1187 G10 appearance.js:10-11,21,26,27 the page shows what storage read back, in one clean order', () => {
  // (a) storage, not the argument, decides: setItem is swallowed, getItem still answers `dark`
  const hole = world({ storage: { value: JSON.stringify({ theme: 'dark', contrast: 'high' }), blackHole: true } });
  assert.deepEqual(hole.call({ theme: 'light', contrast: 'standard' }), { theme: 'dark', contrast: 'high' },
    'appearance.js:11 is the source of truth: applying `next` straight to the DOM is a defect');
  assert.equal(hole.html.attrs['data-theme'], 'dark');
  for (const c of hole.contents()) assert.equal(c, THEME_BG.dark);

  // (b) the full ordered effect trace of one choice
  const w = world({ storage: { value: JSON.stringify({ theme: 'light', contrast: 'high' }) } });
  assert.deepEqual(w.html.attrs, { 'data-theme': 'light', 'data-contrast': 'high' }, 'the boot read what was stored');
  const at = w.mark();
  assert.deepEqual(w.call({ theme: 'dark', contrast: 'high' }), { theme: 'dark', contrast: 'high' });
  assert.deepEqual(w.seams(at), [
    ['setItem', KEY, '{"theme":"dark","contrast":"high"}'],
    ['getItem', KEY],
    ['setAttribute', 'html', 'data-theme', 'dark'],
    ['setAttribute', 'html', 'data-contrast', 'high'],
    ['querySelectorAll', 'meta[name="theme-color"]'],
    ['getAttribute', 'theme-color', 'media'],
    ['setAttribute', 'theme-color', 'content', THEME_BG.dark],
    ['getAttribute', 'theme-color', 'media'],
    ['setAttribute', 'theme-color', 'content', THEME_BG.dark],
    ['querySelector', 'meta[name="color-scheme"]'],
    ['setAttribute', 'color-scheme', 'content', 'dark'],
  ]);

  // (c) a second choice replaces the first everywhere, with nothing stale left
  assert.deepEqual(w.call({ theme: 'light', contrast: 'standard' }), { theme: 'light', contrast: 'standard' });
  assert.equal(w.storage.raw[KEY], '{"theme":"light","contrast":"standard"}');
  assert.deepEqual(w.contents(), [THEME_BG.light, THEME_BG.light], 'no dark hex survives the new choice');
  assert.equal(w.scheme.last('content'), 'light');
  assert.deepEqual(w.html.writes.map((x) => x[1]), ['light', 'high', 'dark', 'high', 'light', 'standard'],
    '<html> is rewritten in place, never appended to');

  // (d) a call with no argument re-reads storage and never writes, and the shape is what Control.tsx:825 needs
  const at2 = w.mark();
  assert.deepEqual(w.call(), { theme: 'light', contrast: 'standard' }, 'no stale in-memory choice: it comes back from storage');
  assert.deepEqual(w.names(at2), ['getItem', 'setAttribute', 'setAttribute', 'querySelectorAll',
    'getAttribute', 'setAttribute', 'getAttribute', 'setAttribute', 'querySelector', 'setAttribute']);
  assert.deepEqual(Object.keys(w.call()), ['theme', 'contrast'], 'the return is exactly {theme, contrast}');
  assert.equal(w.storage.raw[KEY], '{"theme":"light","contrast":"standard"}', 'a no-argument call changes nothing');

  // (e) a fresh page writes nothing at all: the boot at :29 is read-only
  const fresh = world();
  assert.deepEqual(fresh.names(0).filter((n) => n === 'setItem'), [], 'a first launch stores nothing');
  assert.deepEqual(fresh.html.attrs, { 'data-theme': 'system', 'data-contrast': 'system' });
  assertNoPrivilegedAccess(w);
  assertNoPrivilegedAccess(hole);
});
